"""Embedded Project Monitor page.

The first screen is intentionally managerial: project KPIs and a compact
DevelopAid-level Gantt.  RSS and WBS detail appears only on demand.
"""
from __future__ import annotations

import developaid_monitor_manager as _manager
_manager.install()
import developaid_monitor_dashboard as _dashboard
_dashboard.install()

MONITOR_PAGE = r"""<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>DevelopAid · Project Monitor</title><style>
:root{--bg:#f5f6f8;--card:#fff;--text:#18202a;--muted:#667085;--line:#e4e7ec;--navy:#183153;--forecast:#76899f;--risk:#b42318;--warn:#956400;--ok:#247044}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:13px Inter,Arial,sans-serif}.wrap{max-width:1500px;margin:auto;padding:22px}.top{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:14px}h1{font-size:24px;margin:0}.muted{color:var(--muted)}.controls{display:flex;gap:8px;align-items:end;flex-wrap:wrap}.field{display:flex;flex-direction:column;gap:5px}.field label{font-size:11px;color:var(--muted);font-weight:700;text-transform:uppercase}.field input{height:34px;border:1px solid #d0d5dd;border-radius:6px;padding:0 9px;background:white}.btn{height:34px;border:0;border-radius:6px;padding:0 13px;background:var(--navy);color:white;font-weight:650;cursor:pointer}.btn.secondary{background:#475467}.card{background:var(--card);border:1px solid var(--line);border-radius:10px;margin-top:10px;overflow:hidden}.card-head{display:flex;justify-content:space-between;gap:12px;padding:13px 15px;border-bottom:1px solid var(--line);align-items:center}.card-head h2{font-size:14px;margin:0}.card-body{padding:14px 15px}.setup{display:grid;grid-template-columns:1fr 1fr;gap:10px}.setup-box{padding:13px;border:1px solid var(--line);border-radius:8px;background:#fbfcfd}.setup-box h3{font-size:13px;margin:0 0 8px}.setup-box p{font-size:12px;color:var(--muted);line-height:1.45;margin:5px 0 10px}.fileline{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.msg{font-size:12px;margin-top:7px}.err,.bad{color:var(--risk)}.ok,.good{color:var(--ok)}.warn{color:var(--warn)}
.kpis{display:grid;grid-template-columns:repeat(6,1fr);gap:9px}.kpi{border:1px solid var(--line);border-radius:8px;padding:12px;min-height:112px;background:white}.kpi .l{font-size:10px;color:var(--muted);font-weight:750;letter-spacing:.05em;text-transform:uppercase}.kpi .n{font-size:25px;font-weight:760;margin:8px 0 4px}.kpi .s{font-size:11px;color:var(--muted);line-height:1.35}.pf{display:grid;grid-template-columns:repeat(5,1fr)}.pf>div{padding:13px 15px;border-right:1px solid var(--line)}.pf>div:last-child{border-right:0}.pf .v{font-size:18px;font-weight:720;margin-top:5px}.note{padding:10px 15px;background:#fbf7ed;border-top:1px solid #efe2c4;color:#694b12;font-size:11px;line-height:1.4}
.g-axis,.g-row{display:grid;grid-template-columns:310px 1fr 210px}.g-axis{padding:8px 12px;border-bottom:1px solid var(--line);font-size:10px;color:var(--muted)}.axis-time{position:relative;height:18px}.tick{position:absolute;transform:translateX(-50%);white-space:nowrap}.g-row{min-height:62px;border-bottom:1px solid #eef1f4}.g-row:last-child{border-bottom:0}.g-label,.g-metrics{padding:9px 12px}.g-label.clickable{cursor:pointer}.g-title{font-weight:650}.chev{display:inline-block;width:17px;color:#667085}.g-sub{font-size:10px;color:var(--muted);margin-top:4px}.g-lanes{padding:6px 0;position:relative}.lane{height:23px;position:relative;background:repeating-linear-gradient(to right,transparent,transparent calc(12.5% - 1px),#f0f2f5 calc(12.5% - 1px),#f0f2f5 12.5%)}.lane-label{position:absolute;left:4px;top:2px;font-size:9px;color:#98a2b3}.work-plan{position:absolute;top:7px;height:7px;background:#c7cdd5;border-radius:3px}.work-fact{position:absolute;top:7px;height:7px;background:var(--navy);border-radius:3px}.forecast-line{position:absolute;top:9px;height:3px;background:var(--forecast)}.forecast-tail{position:absolute;top:9px;height:3px;background:var(--risk)}.forecast-mark{position:absolute;top:3px;height:15px;width:2px;background:var(--risk)}.cut-mark{position:absolute;top:0;bottom:0;width:1px;background:#344054;opacity:.65}.paybar{position:absolute;bottom:3px;width:4px;transform:translateX(-2px)}.pay-plan{background:#cbd2da}.pay-fact{background:#344054}.g-metrics{text-align:right;font-size:10px;color:var(--muted);line-height:1.45}.metric-main{font-size:11px;color:var(--text);font-weight:650}.level-detail .g-label{padding-left:28px}.level-rss .g-label{padding-left:44px}.level-task .g-label{padding-left:62px}.level-task{background:#fafbfc}.status-bad{color:var(--risk)}.status-good{color:var(--ok)}table{width:100%;border-collapse:collapse}th,td{padding:7px 8px;border-bottom:1px solid #eef1f4;text-align:right;font-size:11px}th:first-child,td:first-child{text-align:left}th{color:var(--muted);font-size:10px}.hidden{display:none}@media(max-width:1100px){.kpis{grid-template-columns:repeat(2,1fr)}.setup{grid-template-columns:1fr}.pf{grid-template-columns:1fr 1fr}.g-axis,.g-row{grid-template-columns:240px 1fr 150px}}
</style></head><body><div class="wrap">
<div class="top"><div><h1>DevelopAid · Project Monitor</h1><div class="muted">Утверждённая модель → факт РСС → текущий прогноз</div></div><div class="controls"><div class="field"><label>Проект</label><input id="project" value="Кутузов Сити"></div><div class="field"><label>Срез</label><input id="cut" type="date"></div><button class="btn" id="refresh">Обновить</button></div></div>
<div class="card"><div class="card-head"><h2>Инициализация проекта</h2><span class="muted" id="baselineState">Baseline загружается один раз</span></div><div class="card-body setup">
<div class="setup-box"><h3>1 · Неизменяемый baseline</h3><p>ГПР с RSS-увязкой фиксирует график. Второй файл фиксирует «Утвержденную фин.модель проекта» и реальную потребность. Эти файлы не заменяются еженедельно.</p><div class="fileline"><input id="baselineFile" type="file" accept=".xlsx"><span class="muted">ГПР / Project Control</span></div><div class="fileline" style="margin-top:7px"><input id="financeFile" type="file" accept=".xlsx"><span class="muted">Утвержденная модель + потребность</span></div><div class="fileline" style="margin-top:7px"><input id="baselineDate" type="date"><button class="btn secondary" id="baselineBtn">Зафиксировать baseline</button></div><div class="msg" id="baselineMsg"></div></div>
<div class="setup-box"><h3>2 · Еженедельное обновление</h3><p><b>Физический факт — только «Реестр выполненных работ».</b><br><b>Денежный факт — только «Реестр платежей».</b><br>Шахматка используется только для группировки.</p><div class="fileline"><input id="rssFile" type="file" accept=".xlsx"><input id="rssDate" type="date"><button class="btn secondary" id="rssBtn">Загрузить РСС</button></div><div class="msg" id="rssMsg"></div><div class="muted" style="margin-top:9px">Следующий регулярный источник — отчёт о продажах; Monitor уже хранит sales snapshots на уровне движка.</div></div>
</div></div>
<div class="card hidden" id="dashCard"><div class="card-head"><h2>Состояние проекта</h2><span class="muted" id="source"></span></div><div class="card-body"><div class="kpis" id="kpis"></div></div></div>
<div class="card hidden" id="pfCard"><div class="card-head"><h2>Проектное финансирование · лимит доведен до реальной потребности</h2><span class="muted">сценарий</span></div><div class="pf" id="pf"></div><div class="note" id="pfNote"></div></div>
<div class="card hidden" id="ganttCard"><div class="card-head"><div><h2>Управленческий Гант · работы + оплаты</h2><div class="muted" style="font-size:11px;margin-top:3px">DevelopAid → RSS → WBS. По умолчанию только крупные блоки. Сортировка идёт по номеру RSS-статьи.</div></div><span class="muted">клик по строке — детализация</span></div><div id="gantt"></div></div>
<div class="card hidden" id="cashCard"><div class="card-head"><h2>Оплаты · помесячно</h2><span class="muted" id="cashNote"></span></div><div class="card-body"><table id="cash"></table></div></div>
<div class="msg" id="viewMsg"></div></div>
<script>
const $=id=>document.getElementById(id),expanded=new Set();let lastView=null;
const today=new Date().toISOString().slice(0,10);$('cut').value=today;$('rssDate').value=today;$('baselineDate').value=today;
function sess(){return localStorage.getItem('session')||localStorage.getItem('developaid_session')||''}function key(){return localStorage.getItem('key')||localStorage.getItem('developaid_key')||''}
async function post(path,p){const r=await fetch(path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.assign({session:sess(),key:key()},p||{}))}),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.detail||('HTTP '+r.status));return d}
async function get(path,p){const q=new URLSearchParams(Object.assign({session:sess(),key:key()},p||{})),r=await fetch(path+'?'+q),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.detail||('HTTP '+r.status));return d}
const b64=f=>new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(String(r.result).split(',')[1]);r.onerror=no;r.readAsDataURL(f)});function msg(id,t,good=false){const e=$(id);e.textContent=t;e.className='msg '+(good?'ok':'err')}function money(v){if(v==null||!isFinite(Number(v)))return '—';const n=Number(v);return Math.abs(n)>=1e9?(n/1e9).toLocaleString('ru-RU',{maximumFractionDigits:2})+' млрд ₽':(n/1e6).toLocaleString('ru-RU',{maximumFractionDigits:1})+' млн ₽'}function pct(v){return v==null?'—':(Number(v)*100).toLocaleString('ru-RU',{maximumFractionDigits:1})+'%'}function date(v){if(!v)return '—';const d=new Date(v);return isNaN(d)?v:d.toLocaleDateString('ru-RU')}function days(a,b){if(!a||!b)return null;return Math.round((new Date(b)-new Date(a))/86400000)}function kpi(l,n,s='',cls=''){return `<div class="kpi"><div class="l">${l}</div><div class="n ${cls}">${n}</div><div class="s">${s}</div></div>`}
async function loadSnapshots(){const p=$('project').value.trim();if(!p)return;try{const s=await get('/monitor/snapshots',{project:p});$('baselineState').textContent=s.baseline&&s.baseline.length?'Baseline создан':'Baseline ещё не создан'}catch(e){}}
$('baselineBtn').onclick=async()=>{const g=$('baselineFile').files[0],f=$('financeFile').files[0],p=$('project').value.trim();if(!g)return msg('baselineMsg','Выберите baseline ГПР');try{msg('baselineMsg','Фиксирую baseline…',true);const d=await post('/monitor/schedule',{project:p,taken_at:$('baselineDate').value,gpr_base64:await b64(g),pm_base64:f?await b64(f):''});msg('baselineMsg',`Baseline создан: ${d.works||'—'} работ`,true);await loadSnapshots()}catch(e){msg('baselineMsg',e.message)}};
$('rssBtn').onclick=async()=>{const f=$('rssFile').files[0],p=$('project').value.trim(),d=$('rssDate').value;if(!f)return msg('rssMsg','Выберите свежую 6.1.2');try{msg('rssMsg','Читаю акты и платежи…',true);await post('/monitor/estimate',{project:p,taken_at:d,filename:f.name,content_base64:await b64(f)});$('cut').value=d;msg('rssMsg','Срез сохранён. Физика и деньги пересчитаны.',true);await refresh()}catch(e){msg('rssMsg',e.message)}};
function renderDash(v){const d=v.dashboard||{},c=d.construction||{},ph=d.physical||{},a=d.advances||{},s=d.schedule||{},sales=d.sales||{};$('dashCard').classList.remove('hidden');const delta=days(s.baseline_finish,s.forecast_finish);$('kpis').innerHTML=kpi('Физическая готовность СМР',pct(ph.completion),`${money(ph.accepted)} актировано · ${pct(ph.completion_vs_bank_limit)} от банковского лимита`,ph.completion!=null&&ph.completion<.5?'warn':'')+kpi('Незакрытые авансы',money(a.unclosed),a.known?`${pct(a.share_of_paid)} от оплаченного СМР`:'нет явного маркера в РСС',a.unclosed?'bad':'')+kpi('Утвержденная потребность СМР',money(c.approved_smr),`лимит РСС ${money(c.limit)} · дефицит ${money(c.limit_gap)}`,c.limit_gap>0?'bad':'good')+kpi('Остаток потребности',money(c.remaining_need),`оплачено ${money(c.paid)} · законтрактовано ${money(c.contracted)}`)+kpi('Продажи',sales.known?'обновлены':'нет отчета',sales.known?(sales.source||'sales snapshot'):(sales.reason||''))+kpi('Окончание строительства',date(s.forecast_finish),`baseline ${date(s.baseline_finish)}${delta!=null?' · Δ '+delta+' дн.':''}`,delta>0?'bad':'good');$('source').textContent=`РСС: ${(d.sources||{}).rss||'—'} · физика: акты · baseline: ${(d.sources||{}).financial_baseline||'—'}`}
function renderPF(v){const p=(v.dashboard||{}).pf||{};$('pfCard').classList.remove('hidden');$('pf').innerHTML=`<div><div class="muted">Доп. лимит стройки</div><div class="v ${p.additional_limit>0?'bad':''}">${money(p.additional_limit)}</div></div><div><div class="muted">Долг ПФ на РВЭ</div><div class="v">${money(p.debt_at_completion)}</div></div><div><div class="muted">Эскроу на РВЭ</div><div class="v">${money(p.escrow_at_completion)}</div></div><div><div class="muted">Погашение ПФ</div><div class="v">${p.available?(p.repaid?'ПОЛНОСТЬЮ':'ОСТАТОК '+money(p.residual_debt)):'—'}</div></div><div><div class="muted">LLCR</div><div class="v">${p.llcr==null?'—':Number(p.llcr).toFixed(2)}</div></div>`;$('pfNote').textContent=p.available?(p.repaid?'Прогноз: ПФ погашается полностью.':'Прогноз: после РВЭ остаётся долг '+money(p.residual_debt)):(p.reason||'Сценарий пока не рассчитан')}
function visibleRows(nodes,depth=0,out=[]){for(const n of nodes||[]){out.push({node:n,depth});if(expanded.has(n.key)&&n.children&&n.children.length){if(n.level==='rss'){for(const t of n.children)out.push({node:Object.assign({key:'task:'+String(t.id||t.wbs),level:'task'},t),depth:depth+1})}else visibleRows(n.children,depth+1,out)}}return out}function entries(o){return Object.entries(o||{}).sort((a,b)=>a[0].localeCompare(b[0]))}function controlCode(n){return {'Подготовка':'2.1','Основные объекты':'2.2','Наружные сети':'2.4','Благоустройство':'2.5','Служба заказчика':'2.6','Проектирование':'2.7'}[n]||''}
function renderGantt(v){const roots=(v.schedule||{}).management||[];if(!roots.length){$('ganttCard').classList.add('hidden');return}$('ganttCard').classList.remove('hidden');const flat=visibleRows(roots),dates=[];for(const {node:n} of flat){[n.plan_start,n.plan_finish,n.forecast_finish].filter(Boolean).forEach(x=>dates.push(new Date(x)));for(const [m] of [...entries((n.payments||{}).plan),...entries((n.payments||{}).fact)])dates.push(new Date(m))}dates.push(new Date(v.cut));let min=new Date(Math.min(...dates)),max=new Date(Math.max(...dates));min=new Date(min.getFullYear(),min.getMonth(),1);max=new Date(max.getFullYear(),max.getMonth()+1,1);const span=Math.max(86400000,max-min),pos=x=>Math.max(0,Math.min(100,(new Date(x)-min)/span*100)),cp=pos(v.cut);let ticks='',tm=new Date(min),i=0;while(tm<=max){if(i%3===0)ticks+=`<span class="tick" style="left:${pos(tm)}%">${tm.toLocaleDateString('ru-RU',{month:'short',year:'2-digit'})}</span>`;tm=new Date(tm.getFullYear(),tm.getMonth()+1,1);i++}let h=`<div class="g-axis"><div>Блок / статья</div><div class="axis-time">${ticks}</div><div style="text-align:right">План / факт / прогноз</div></div>`;for(const {node:n} of flat){const level=n.level||'task',kids=level!=='task'&&n.children&&n.children.length,open=expanded.has(n.key),l=n.plan_start?pos(n.plan_start):0,r=n.plan_finish?pos(n.plan_finish):l,w=Math.max(0,r-l),ap=n.actual_progress==null?null:Math.min(1,Math.max(0,Number(n.actual_progress))),fw=ap==null?0:w*ap,fp=n.forecast_finish?pos(n.forecast_finish):null,pay=n.payments||{},plan=entries(pay.plan),fact=entries(pay.fact),mx=Math.max(1,...plan.map(x=>+x[1]||0),...fact.map(x=>+x[1]||0));let bars='';for(const [m,x] of plan)bars+=`<i class="paybar pay-plan" style="left:${pos(m)}%;height:${Math.max(2,14*(+x||0)/mx)}px"></i>`;for(const [m,x] of fact)bars+=`<i class="paybar pay-fact" style="left:${pos(m)}%;height:${Math.max(2,14*(+x||0)/mx)}px"></i>`;const prefix=level==='control'?controlCode(n.name):(level==='rss'?(n.code||''):'');const tail=fp!=null&&fp>r?`<i class="forecast-tail" style="left:${r}%;width:${fp-r}%"></i>`:'';const forecast=fp!=null?`<i class="forecast-line" style="left:${Math.min(r,fp)}%;width:${Math.abs(fp-r)}%"></i><i class="forecast-mark" style="left:${fp}%"></i>${tail}`:'';h+=`<div class="g-row level-${level}"><div class="g-label ${kids?'clickable':''}" data-key="${n.key||''}"><div class="g-title ${n.status==='ОТСТАВАНИЕ'||n.status==='НЕТ ТЕМПА / РИСК'?'status-bad':''}"><span class="chev">${kids?(open?'▾':'▸'):''}</span>${prefix?prefix+' · ':''}${n.name||n.wbs||''}</div><div class="g-sub">${n.status||''}</div></div><div class="g-lanes"><div class="lane"><span class="lane-label">работы</span><i class="cut-mark" style="left:${cp}%"></i>${w?`<i class="work-plan" style="left:${l}%;width:${w}%"></i>`:''}${fw?`<i class="work-fact" style="left:${l}%;width:${fw}%"></i>`:''}${forecast}</div><div class="lane"><span class="lane-label">оплаты</span><i class="cut-mark" style="left:${cp}%"></i>${bars}</div></div><div class="g-metrics"><div class="metric-main">План ${pct(n.plan_progress)} · факт ${pct(n.actual_progress)}</div><div>Forecast ${date(n.forecast_finish)}${n.delta_days!=null?' · Δ '+n.delta_days+' дн.':''}</div><div>${pay.fact_total?money(pay.fact_total):''}</div></div></div>`}$('gantt').innerHTML=h;document.querySelectorAll('.g-label.clickable').forEach(el=>el.onclick=()=>{const k=el.dataset.key;expanded.has(k)?expanded.delete(k):expanded.add(k);renderGantt(lastView)})}
function renderCash(v){const p=v.payments||{},rows=p.rows||[];$('cashCard').classList.toggle('hidden',!rows.length);$('cashNote').textContent=p.known?'план baseline / факт из Реестра платежей':'факт из Реестра платежей';$('cash').innerHTML='<tr><th>Месяц</th><th>План</th><th>Факт</th><th>Δ</th></tr>'+rows.map(r=>`<tr><td>${String(r.month).slice(0,7)}</td><td>${money(r.plan)}</td><td>${money(r.fact)}</td><td>${money(r.delta)}</td></tr>`).join('')}
async function refresh(){const p=$('project').value.trim(),cut=$('cut').value;if(!p||!cut)return;try{const d=await post('/monitor/view',{project:p,cut:cut,upto:''}),v=d.snapshot||d.view||d.report||d;lastView=v;renderDash(v);renderPF(v);renderGantt(v);renderCash(v);msg('viewMsg','')}catch(e){msg('viewMsg',e.message)}}$('refresh').onclick=refresh;$('project').onchange=loadSnapshots;loadSnapshots().then(refresh);
</script></body></html>"""
